css:
/* --- хаб «Бестиарий»: карточки категорий --- */
body{background:#f3f1ec}
#sp-page-builder .sppb-row > .sppb-column{display:flex;background:#fff;padding-left:7.5px;padding-right:7.5px}
#sp-page-builder .sppb-addon-wrapper{display:flex;flex-direction:column;width:100%}
#sp-page-builder .sppb-addon-raw_html{margin-top:auto}
#sp-page-builder .sppb-addon-heading .sppb-addon-title{font-size:1.25rem;font-weight:400;line-height:1.3;text-transform:uppercase;letter-spacing:.02em;margin:0}

/* --- кнопка «Подробнее» --- */
.wrapper{display:flex;justify-content:center}
.cta{display:flex;padding:10px 45px;text-decoration:none;font-family:'Poppins','Segoe UI',Roboto,Arial,sans-serif;font-size:20px;font-style:italic;font-weight:900;color:#fff;background:#000;transition:1s;box-shadow:6px 6px 0 gray;transform:skewX(-15deg)}
.cta:focus{outline:none}
.cta:hover{transition:.5s;box-shadow:10px 10px 0 #FBC638;text-decoration:none;color:#fff}
.cta span{transform:skewX(15deg)}
.cta span:nth-child(2){width:20px;margin-left:30px;position:relative;top:12%;transition:.5s;margin-right:0}
.cta:hover span:nth-child(2){transition:.5s;margin-right:45px}
.cta path.one{transition:.4s;transform:translateX(-60%)}
.cta path.two{transition:.5s;transform:translateX(-30%)}
.cta:hover path.three{animation:cta-color-anim 1s infinite .2s}
.cta:hover path.one{transform:translateX(0%);animation:cta-color-anim 1s infinite .6s}
.cta:hover path.two{transform:translateX(0%);animation:cta-color-anim 1s infinite .4s}
@keyframes cta-color-anim{0%{fill:#fff}50%{fill:#FBC638}100%{fill:#fff}}
